class Solution:
    def lastSubstring(self, s: str) -> str:
        left, right, l = 0, 1, 0
        while right+l < len(s):
            if s[left+l] == s[right+l]:
                l += 1
                continue
            if s[left+l] > s[right+l]:
                right += l+1
            else:
                left = max(right, left+l+1)
                right = left+1
            l = 0
        return s[left:]

from typing import List
class Solution:
    def numSmallerByFrequency(self, queries: List[str], words: List[str]) -> List[int]:
        def _f(s):
            d = Counter(s)
            d =dict(sorted(d.items(), key=lambda item: item[0]))
            for x in d:
                return d[x]

        freq = []
        for w in words:
            n1 = _f(w)
            freq.append(n1)

        freq.sort(reverse=True)

        res = []
        for q in queries:
            n = _f(q)
            c=0
            for n1 in freq:
                if n < n1:
                    c+=1
                else:
                    break
            res.append(c)

        return res

class Solution:
    def numPrimeArrangements(self, n: int) -> int:
        primes = set()
        for i in range(2,n+1):
            if all(i%p != 0 for p in primes):
                primes.add(i)
        M = 10**9 + 7
        def fact(k):
            res = 1
            for i in range(2,k+1):
                res = (res*i)%M
            return res
        return fact(len(primes))*fact(n-len(primes))%M

class Solution:
    def numPrimeArrangements(self, n: int) -> int:
        def count_primes(n):
            if n <= 1:
                return 0
            is_prime = [True]*((n+1)//2)
            cnt = len(is_prime)
            for i in range(3, n+1, 2):
                if i*i > n:
                    break
                if not is_prime[i//2]:
                    continue
                for j in range(i*i, n+1, 2*i):
                    if not is_prime[j//2]:
                        continue
                    cnt -= 1
                    is_prime[j//2] = False
            return cnt

        def factorial(n):
            result = 1
            for i in range(2, n+1):
                result = (result*i)%MOD
            return result

        MOD = 10**9+7
        cnt = count_primes(n)
        return factorial(cnt) * factorial(n-cnt) % MOD
